[BEGIN]
module TopModule(
    input  logic clk,
    input  logic areset,
    input  logic in,
    output logic out
);

    typedef enum logic {A = 1'b0, B = 1'b1} state_t;
    state_t state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= B;
        end else begin
            case (state)
                A: state <= in ? A : B;
                B: state <= in ? B : A;
                default: state <= B;
            endcase
        end
    end

    assign out = (state == B);

endmodule
[DONE]
